        clave externa FKFFBDD9D8ECCE8750;

    eliminar tabla si existe jpa06_article;

    eliminar tabla si existe jpa06_category;

    crear tabla jpa06_article (
        id bigint no nulo autoincrementado,
        version integer not null,
        nombre varchar(30),
        category_id bigint not null,
        clave principal (id)
    ) ENGINE=InnoDB;

    crear tabla jpa06_category (
        id bigint no nulo auto_increment,
        versión entero no nulo,
        nombre varchar(30),
        clave principal (id)
    ) ENGINE=InnoDB;

    ALTER TABLE jpa06_article
        añadir índice FKFFBDD9D8ECCE8750 (category_id),
        añadir restricción FKFFBDD9D8ECCE8750
        clave externa (category_id)
que hace referencia a jpa06_categorie (id);
</code></pre> <ul> <li>en [1], la base de datos, y en [2], su DDL (MySQL5)   </li> </ul> <p>Un artículo A(id, versión, nombre) pertenece exactamente a una categoría C(id, versión, nombre). Una categoría C puede contener 0, 1 o más artículos. Tenemos una relación uno a muchos (Categoría -&gt; Artículo) y la relación inversa muchos a uno (Artículo -&gt; Categoría). Esta relación se representa mediante la clave externa que la tabla [article] tiene en la tabla [category] (líneas 24-28 del DDL).</p> <p></p>
